function generateSlots(o) {
  const cfg = o.cfg, busy = o.busy, fromMs = o.fromMs, toMs = o.toMs, prefDate = o.prefDate;
  const v = cfg.viewing, tz = cfg.agency.timezone;
  const slotMs = v.slot_minutes * 60000, bufMs = v.buffer_minutes * 60000;
  const st = hm(v.start), en = hm(v.end);
  const first = localParts(fromMs, tz);
  const build = (timeOfDay) => {
    const all = [];
    const span = Math.ceil((toMs - fromMs) / 86400000) + 1;
    for (let i = 0; i <= span; i++) {
      const dd = addDays(first.y, first.m, first.d, i);
      if (!v.days.includes(isoDow(dd.y, dd.m, dd.d))) continue;
      for (let mins = st.h * 60 + st.m; mins + v.slot_minutes <= en.h * 60 + en.m; mins += v.step_minutes) {
        const s = zonedToUtc(dd.y, dd.m, dd.d, Math.floor(mins / 60), mins % 60, tz);
        const e = s + slotMs;
        if (s < fromMs || s >= toMs) continue;
        if (busy.some((b) => s - bufMs < b.e && e + bufMs > b.s)) continue;
        const hr = Math.floor(mins / 60);
        if (timeOfDay === 'morning' && hr >= 12) continue;
        if (timeOfDay === 'afternoon' && (hr < 12 || hr >= 17)) continue;
        if (timeOfDay === 'evening' && hr < 17) continue;
        all.push({ startMs: s, endMs: e, dateKey: dd.y + '-' + String(dd.m).padStart(2, '0') + '-' + String(dd.d).padStart(2, '0') });
      }
    }
    return all;
  };
  let tod = o.timeOfDay && ['morning', 'afternoon', 'evening'].includes(o.timeOfDay) ? o.timeOfDay : '';
  let all = build(tod);
  let relaxed = false;
  if (!all.length && tod) { all = build(''); relaxed = true; }
  let picks = [];
  const same = prefDate ? all.filter((x) => x.dateKey === prefDate) : [];
  if (same.length) {
    const idx = Array.from(new Set([0, Math.floor((same.length - 1) / 2), same.length - 1]));
    picks = idx.map((i) => same[i]);
  } else {
    const seen = new Set();
    for (const x of all) { if (!seen.has(x.dateKey)) { seen.add(x.dateKey); picks.push(x); } if (picks.length >= 3) break; }
  }
  return { relaxed: relaxed, slots: picks.map((x) => ({ startISO: iso(x.startMs), endISO: iso(x.endMs), label: fmtLabel(x.startMs, tz) })) };
}

const prev = $('[Availability] Prep FreeBusy').item.json;
const resp = $json;
const ctx = Object.assign({}, prev);
const cfg = ctx.cfg;

const fail = (code, msg) => {
  ctx.vapiResult = { toolCallId: ctx.toolCallId, result: JSON.stringify({ ok: false, error: code, message: msg }) };
  ctx.sideEffects = false;
  return { json: ctx };
};

const tz = cfg.agency.timezone;
if (resp.error) return fail('calendar_unavailable', 'Could not read the calendar right now.');
const cals = resp.calendars || {};
const cal = cals[cfg.google.calendar_id] || Object.values(cals)[0] || {};
if (cal.errors && cal.errors.length) return fail('calendar_unavailable', 'Calendar not accessible.');
const busy = (cal.busy || []).map((b) => ({ s: Date.parse(b.start), e: Date.parse(b.end) }));
const g = generateSlots({ cfg: cfg, busy: busy, fromMs: Date.parse(ctx.fbBody.timeMin), toMs: Date.parse(ctx.fbBody.timeMax), prefDate: ctx.prefDate, timeOfDay: (ctx.args || {}).timeOfDay });
const out = { ok: true, timezone: tz, slots: g.slots.map((s) => ({ startISO: s.startISO, label: s.label })) };
if (!g.slots.length) out.message = 'No openings found in that window. Try another day.';
if (g.relaxed) out.note = 'Nothing in the requested time of day; these are the nearest alternatives.';
ctx.vapiResult = { toolCallId: ctx.toolCallId, result: JSON.stringify(out) };
ctx.sideEffects = false;

return { json: ctx };

const results = [];
const degraded = [];
for (const it of $input.all()) {
  const j = it.json;
  if (j.vapiResult) results.push(j.vapiResult);
  if (Array.isArray(j.degraded)) for (const d of j.degraded) degraded.push(d);
}
return [{ json: { response: { results: results }, degraded: degraded } }];

const names = ["[Availability] Compute Slots"];
const out = [];
for (const n of names) {
  try {
    const node = $(n);
    if (node.isExecuted === false) continue;
    for (const it of node.all()) { if (it.json.sideEffects) out.push({ json: it.json }); }
  } catch (e) { /* node did not run for this request */ }
}
return out;

